import http from 'node:http';

const menu = [{ id: 1, nama: 'Kopi Susu' }, { id: 2, nama: 'Teh Tarik' }];
function kirimJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}
const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  if (url.pathname === '/menu') return kirimJson(res, 200, menu);
  if (url.pathname === '/sehat') {
    res.statusCode = 204;
    return res.end();
  }
  kirimJson(res, 404, { error: `Jalur ${url.pathname} tidak ditemukan` });
});
server.listen(3000);

for (const jalur of ['/menu', '/sehat', '/kasir']) {
  const r = await fetch('http://localhost:3000' + jalur);
  console.log(jalur, r.status, r.statusText);
}
server.close();

