import http from 'node:http';
const menu = ['Kopi Susu', 'Teh Tarik'];
function kirimJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}
const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  if (url.pathname === '/menu') return kirimJson(res, 200, menu);
  const bagian = url.pathname.split('/');
  if (bagian[1] === 'menu' && bagian.length === 3) {
    const m = menu[Number(bagian[2]) - 1];
    if (m) return kirimJson(res, 200, m);
  }
  kirimJson(res, 404, { error: 'Tidak ditemukan' });
});
server.listen(3000);
const r = await fetch('http://localhost:3000/menu');
console.log(r.status, await r.json());
const r2 = await fetch('http://localhost:3000/kasir');
console.log(r2.status, await r2.json());
const r3 = await fetch('http://localhost:3000/menu/2');
console.log(r3.status, await r3.json());
server.close();

